{
  "findings": [
    {
      "ref": "[D531]",
      "area": "contact",
      "claim": "A parent reports that younger children are receiving unsolicited friend requests from strangers on Roblox.",
      "stance": "risk",
      "quote": "some children have reported unsolicited friend requests from strangers."
    },
    {
      "ref": "[D531]",
      "area": "contact",
      "claim": "A parent reports that the platform allows voice chat with strangers by default and it can be turned off via parental controls.",
      "stance": "mitigation",
      "quote": "Players must go through this verification process to engage in certain features like [Spatial (3D) Voice]."
    },
    {
      "ref": "[D531]",
      "area": "money",
      "claim": "A parent reports that the game encourages spending real money on in‑game currency to unlock features and can be used to exploit children.",
      "stance": "risk",
      "quote": "the temptation or requirement to buy in–game currency to improve gameplay can also be used to exploit children."
    },
    {
      "ref": "[D531]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal data for advertising and may share it with third parties, and that this data can be deleted.",
      "stance": "neutral",
      "quote": "The platform's Terms of Use say that users under the age of 18 require parental consent to use the services."
    },
    {
      "ref": "[D531]",
      "area": "age_gating",
      "claim": "A parent reports that the age verification process requires an ID document and selfie match, but it is optional and not enforced for all users.",
      "stance": "mitigation",
      "quote": "Players must go through this verification process to engage in certain features like [Spatial (3D) Voice]. This involves an ID document check and selfie match."
    },
    {
      "ref": "[D531]",
      "area": "content",
      "claim": "A parent reports that the game Brookhaven contains sexualised content, including avatars simulating sex acts and dress‑up items that can be used to simulate sexual activity.",
      "stance": "risk",
      "quote": "avatars were seen simulating sex acts, using the power of suggestion and in‑game chat functions."
    },
    {
      "ref": "[D531]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox Corporation has faced regulatory scrutiny and fines for data‑privacy and child‑safety issues.",
      "stance": "risk",
      "quote": "Roblox has an opt‑in age verification feature."
    }
  ]
